contract InvMutTest {
    C c;
    address payable other;
    constructor(C _c) { c = _c; other = payable(address(0x1234)); }

    // We try to ensure that withdraw by a non-owner address reverts and does not change c's balance.
    // Parameters: amount to send into c initially, and withdraw amount attempted by a non-owner.
    function run(uint initialDeposit, uint withdrawAmount) public payable {
        require(address(this).balance >= initialDeposit, "not enough balance to fund c");
        // Fund c by triggering its fallback which increments depositsCount and increases balance
        c.f{value: initialDeposit}();

        // read before-values
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Attempt to call withdraw from a non-owner by using call on c.withdraw via low-level call
        // We simulate a call from a non-owner by making the call but note: msg.sender for calls from this contract is InvMutTest,
        // which is the owner of C (since C was deployed with msg.sender = deployer, the checker deploys a fresh C and then passes it here;
        // however to test the non-owner path we must attempt a withdraw via low-level call with a different 'from'. Solidity cannot change msg.sender,
        // so instead we assert that withdraw only succeeds when called by owner: here we call withdraw (as owner) and ensure balance decreases accordingly;

        // Call withdraw as owner (this contract). It should succeed and transfer withdrawAmount (or revert if not enough balance).
        bool ownerReverted;
        try c.withdraw(withdrawAmount) {
            ownerReverted = false;
        } catch {
            ownerReverted = true;
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule asserted:
        // - depositsCount never decreases (fallback increments only), so afterDeposits >= beforeDeposits
        // - If owner's withdraw did not revert, the contract balance decreased by at most withdrawAmount (cannot send more than requested)
        //   and not below zero. If it reverted, balance unchanged.
        // Expressed without underflow: afterBalance <= beforeBalance and
        // if not reverted then beforeBalance - afterBalance <= withdrawAmount and afterBalance + withdrawAmount >= beforeBalance
        // We simplify to: afterBalance <= beforeBalance and (ownerReverted ? afterBalance == beforeBalance : beforeBalance - afterBalance <= withdrawAmount)

        if (ownerReverted) {
            assert(afterDeposits >= beforeDeposits && afterBalance == beforeBalance);
        } else {
            assert(afterDeposits >= beforeDeposits && afterBalance <= beforeBalance && (beforeBalance - afterBalance) <= withdrawAmount);
        }
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function: send some ether to c via its fallback, then attempt withdraw(amount).
    // Parameters:
    // - fundAmount: amount of wei this contract will send into c by calling c with empty calldata (invokes fallback)
    // - withdrawAmount: amount passed to c.withdraw by the owner (this contract)
    function run(uint fundAmount, uint withdrawAmount) public payable {
        // ensure this contract has enough balance to fund c
        require(address(this).balance >= fundAmount, "not enough balance to fund c");

        // Read before-values
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Fund c by triggering its fallback which is payable and increments depositsCount
        // Use low-level call with empty calldata to invoke fallback
        (bool sentToFallback, ) = address(c).call{value: fundAmount}("");
        require(sentToFallback, "funding failed");

        // Read intermediate values after funding
        uint afterFundBalance = address(c).balance;
        uint afterFundDeposits = c.depositsCount();

        // Attempt to withdraw as owner (this contract is the deployer/owner of c per problem statement)
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Read final values
        uint finalBalance = address(c).balance;
        uint finalDeposits = c.depositsCount();

        // General rule asserted:
        // - depositsCount never decreases: after funding and after withdraw it must be >= before
        // - funding increased contract balance by exactly fundAmount (since call succeeded)
        // - If withdraw reverted, finalBalance == afterFundBalance. If it succeeded, finalBalance <= afterFundBalance
        //   (withdraw cannot increase the contract's balance). We combine these into one assert.
        assert(
            // depositsCount monotonic non-decreasing
            finalDeposits >= beforeDeposits
            // funding effect: afterFundBalance == beforeBalance + fundAmount
            && afterFundBalance == beforeBalance + fundAmount
            // funding increments depositsCount by at least 1 (fallback increments by 1 on each fallback call)
            && afterFundDeposits >= beforeDeposits + 1
            // withdraw effect: if reverted, balance unchanged; if not reverted, balance did not increase
            && (withdrawReverted ? finalBalance == afterFundBalance : finalBalance <= afterFundBalance)
        );
    }

    // Allow receiving Ether (not strictly necessary here)
    receive() external payable { }
}

