        require(address(this).balance >= fundAmount, "insufficient balance to fund");

        // Observe before state
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Send Ether to c using its payable fallback by calling address(c).call with empty calldata.
        // This is a state-changing external call on c but not through c.<fn>(); that's allowed per constraints
        // as long as it's a top-level statement. (It triggers fallback in C.)
        (bool sent, ) = address(c).call{value: fundAmount}("");
        require(sent, "funding call failed");

        // Observe after funding
        uint afterFundBalance = address(c).balance;
        uint afterFundDeposits = c.depositsCount();

        // Attempt owner withdraw (this contract is owner since it deployed C)
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Observe final balance and deposits
        uint finalBalance = address(c).balance;
        uint finalDeposits = c.depositsCount();

        // General rule asserted:
        // 1) fallback funding increased depositsCount by at least 1
        // 2) funding increased contract balance by exactly fundAmount
        // 3) withdraw cannot increase the contract balance; if withdraw reverted the balance is unchanged
        assert(
            afterFundDeposits >= beforeDeposits + 1
            && afterFundBalance == beforeBalance + fundAmount
            && finalDeposits >= afterFundDeposits
            && (withdrewReverted ? finalBalance == afterFundBalance : finalBalance <= afterFundBalance)
        );
    }

    receive() external payable { }
}

