contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = address(this); }

    // We will attempt to call withdraw/withdrawAll as non-owner (this contract is the owner because it deployed C),
    // so to test non-owner behavior we need to simulate a call originating from a different address.
    // However the checker runs run(...) once and msg.sender for calls to c will be this contract.
    // Instead we assert a general rule about behavior when this contract (owner) calls withdraw/withdrawAll:
    // After a successful withdraw or withdrawAll by owner, the contract's balance decreases by at most the withdrawn amount
    // and depositsCount does not decrease.

    // The single public test function takes parameters to exercise withdrawing and sending.
    function run(address payable target, uint amount, uint withdrawAmount, bool doSend) public payable {
        require(true);
        // fund this test contract so it can send to c if needed
        // Send some Ether into c via fallback by calling with value
        if (amount > 0) {
            require(address(this).balance >= amount, "insufficient balance to fund c");
            // send Ether to c to increase its balance and trigger fallback (which increments depositsCount)
            (bool s,) = address(c).call{value: amount}("");
            // we don't require success here; fallback will run if accepted
        }

        // record before-values
        uint beforeDeposits = c.depositsCount();
        uint beforeCbalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;

        bool withdrawReverted;
        // attempt withdraw call by owner (this contract is owner) — must not revert for allowed values
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Optionally test sendMoney: owner can call sendMoney to an arbitrary target; record result by checking contract balances.
        bool sendReverted;
        uint beforeTargetBalance = target.balance;
        if (doSend) {
            // ensure this contract has enough balance to instruct c to send (c must have funds)
            try c.sendMoney(target, withdrawAmount) {
                sendReverted = false;
            } catch {
                sendReverted = true;
            }
        } else {
            sendReverted = true; // not invoked
        }

        uint afterDeposits = c.depositsCount();
        uint afterCbalance = address(c).balance;
        uint afterThisBalance = address(this).balance;
        uint afterTargetBalance = target.balance;

        // General invariant asserted:
        // 1) depositsCount never decreases (fallback only increments it) — so afterDeposits >= beforeDeposits
        // 2) If withdraw did not revert, then c.balance decreased by at most withdrawAmount (cannot decrease below zero)
        //    and this contract's balance increased by at most withdrawAmount.
        // 3) If sendMoney was called and did not revert, target.balance increased by at most withdrawAmount and c.balance decreased accordingly.
        assert(
            afterDeposits >= beforeDeposits
            && (
                withdrawReverted
                || (beforeCbalance >= afterCbalance && beforeCbalance - afterCbalance <= withdrawAmount && afterThisBalance >= beforeThisBalance && afterThisBalance - beforeThisBalance <= withdrawAmount)
            )
            && (
                !doSend || sendReverted || (afterTargetBalance >= beforeTargetBalance && afterTargetBalance - beforeTargetBalance <= withdrawAmount && beforeCbalance - afterCbalance >= (doSend && !sendReverted ? (afterTargetBalance - beforeTargetBalance) : 0))
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: target for sendMoney, fundAmount to send into c via fallback, withdrawAmount to withdraw, doSend to invoke sendMoney
    function run(address payable target, uint fundAmount, uint withdrawAmount, bool doSend) public payable {
        require(true);

        // If we will fund c, ensure this contract has the Ether to do so
        if (fundAmount > 0) {
            require(address(this).balance >= fundAmount);
            // Top-level call that sends Ether to c, triggering fallback which increments depositsCount
            (bool sent, ) = address(c).call{value: fundAmount}("");
            // allow failure; fallback may revert if gasless, but that's okay for the test
            sent;
        }

        // Record observable before-values
        uint beforeDeposits = c.depositsCount();
        uint beforeCbalance = address(c).balance;

        // Attempt withdraw as owner (this contract is owner since it deployed c in the harness)
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Optionally attempt sendMoney
        bool sendReverted = true;
        if (doSend) {
            try c.sendMoney(target, withdrawAmount) {
                sendReverted = false;
            } catch {
                sendReverted = true;
            }
        }

        // Read after-values
        uint afterDeposits = c.depositsCount();
        uint afterCbalance = address(c).balance;

        // Assert the general rule:
        // 1) depositsCount never decreases (fallback only increments it)
        // 2) If withdraw did not revert then c.balance did not increase (it decreased by at most withdrawAmount)
        // 3) If sendMoney did not revert then c.balance did not increase (it decreased by at most withdrawAmount)
        assert(
            afterDeposits >= beforeDeposits
            && (
                withdrawReverted || beforeCbalance >= afterCbalance
            )
            && (
                (doSend && !sendReverted) || (!doSend) || beforeCbalance >= afterCbalance || (doSend && sendReverted)
            )
        );
    }

    receive() external payable { }
}

