contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Send Ether amount to c to trigger fallback; also allow a target for sendMoney test
    function run(address payable target, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // read before values
        uint256 beforeCount = c.depositsCount();
        uint256 beforeBal = address(c).balance;

        // perform the call that will send Ether to c and trigger its fallback
        bool reverted;
        try c.sendMoney(target, 0) {
            // if sendMoney succeeds with zero value, no effect on balance
            reverted = false;
        } catch {
            // ignore revert from sendMoney (target may reject), continue to test fallback behaviour below
            reverted = true;
        }

        // Now send Ether directly to c to trigger fallback (this is the primary action under test)
        // This must be a top-level call that changes c's state
        c.f{value: amount}();

        // read after values
        uint256 afterCount = c.depositsCount();
        uint256 afterBal = address(c).balance;

        // General rule: if the direct value-send did not revert (we reached the assert, so it didn't), then depositsCount increased by 1 and balance increased by amount
        assert(afterCount == beforeCount + 1 && afterBal == beforeBal + amount);
    }

    receive() external payable {}
}

