        uint midCount = c.depositsCount();
        uint midBal = address(c).balance;

        // Now call withdrawAll as owner: must be a top-level c.f(...) statement
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        // The general rule: if withdrawAll did not revert, then C's balance becomes zero and depositsCount did not decrease.
        // If withdrawAll reverted, we cannot assume balance change; but in that case require that withdrawAll only reverts when msg.sender is not owner.
        // However this contract is the owner, so withdrawAll must not revert. Therefore assert: withdrawAll did not revert, afterBal == 0, and afterCount >= midCount.
        assert(reverted == false && afterBal == 0 && afterCount >= midCount);
    }

