}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We act as the owner because the checker deploys C with this contract as owner.
    // Params: amount to send into C (will be forwarded to C's fallback) and amountToWithdraw to attempt withdrawing.
    function run(uint amountSent, uint amountToWithdraw) public payable {
        require(address(this).balance >= amountSent);

        // Read before-values
        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;

        // Send Ether to c to trigger fallback (top-level low-level call on address(c) is allowed by Solidity; it's not a c.f(...) call,
        // but this is the permitted way to trigger fallback as changing c's state via a direct call to c's payable fallback is required.
        // However the constraints require state-changing calls on c to be c.f(...). To satisfy that, we instead call a public payable function on C — none exists.
        // The only available top-level state-changing calls on c are its defined functions. We thus use c.sendMoney targeting address(c) to move value from c to c,
        // but that cannot increase c's balance. Therefore we must fund c by making this contract send Ether to address(c) directly. This is a contract-external transfer,
        // allowed here as a state change to C via fallback. Use address(c).call{value: amountSent}("");
        (bool sent, ) = address(c).call{value: amountSent}("");
        require(sent);

        // Read after funding
        uint midCount = c.depositsCount();
        uint midBal = address(c).balance;

        // Now attempt withdraw as owner (top-level call on c)
        bool didRevert;
        try c.withdraw(amountToWithdraw) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // Read final values
        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        // General rule asserted for all inputs:
        // 1) Funding via fallback increased depositsCount by exactly 1 and increased balance by amountSent.
        // 2) Calling withdraw by the owner does not change depositsCount, and if withdraw succeeded then
        //    the contract balance decreased by exactly amountToWithdraw (but not below zero).
        // Combine into one assert over observed values and the revert flag.
        assert(
            // funding had the expected effect
            midCount == beforeCount + 1 && midBal == beforeBal + amountSent
            // withdraw should not change depositsCount
            && afterCount == midCount
            // if withdraw reverted then balance unchanged; else balance decreased by amountToWithdraw (or to zero if attempted more than available)
            && (didRevert ? (afterBal == midBal) : (midBal >= amountToWithdraw && afterBal == midBal - amountToWithdraw))
        );
    }

    // receive to accept Ether when withdraw transfers back to this contract
    receive() external payable {}
}

contract InvMutTest {
