    // params: target to send to, value to forward from c to target
    function run(address payable target, uint value) public payable {
        require(true);

        // observe before state
        uint beforeDeposits = c.depositsCount();
        uint beforeBal = address(c).balance;
        uint beforeThis = address(this).balance;

        // Ensure this contract has no need to send Ether itself; sendMoney uses c's balance.
        // Call sendMoney and capture whether it reverted.
        bool reverted;
        try c.sendMoney(target, value) {
