            // If value is greater than beforeBal, the low-level call in sendMoney would still attempt and revert
            // (require on __sent_result100), so successful non-revert implies value <= beforeBal and balance decreases by value.
            assert(value <= beforeBal);
            assert(afterBal == beforeBal - value);
        }
    }

    receive() external payable {}
}

