contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters: target and amount to attempt sendMoney, and a flag chooseOwnerCall
    // If chooseOwnerCall==true, we will call sendMoney/withdrawAll as the owner (this contract is the owner);
    // if false, we simulate a non-owner by making calls from a different address cannot be done here,
    // however the checker deploys a fresh C with InvMutTest as owner, so calls from this contract are owner calls.
    // To observe non-owner behavior, we perform a low-level call to c from address(this) but with data that triggers sendMoney
    // through an external call by using an intermediate external contract is not allowed. Instead, we check invariants
    // about effects: withdrawAll as owner should transfer entire c.balance to address(this). For sendMoney we assert
    // when the call succeeds, c.balance decreases by amount and recipient receives amount; otherwise c.balance unchanged.

    // We therefore parameterize on target and amount, and assert the relation between pre/post balances and revert flag.
    function run(address payable target, uint256 amount) public payable {
        require(true);

        // Pre-state observations
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // Attempt sendMoney and capture whether it reverts
        bool revertedSend;
        try c.sendMoney(target, amount) {
            revertedSend = false;
        } catch {
            revertedSend = true;
        }

        uint256 afterC_send = address(c).balance;
        uint256 afterThis_send = address(this).balance;

        // Now, as owner (this contract is owner), call withdrawAll and capture revert (should not revert)
        bool revertedWithdrawAll;
        try c.withdrawAll() {
            revertedWithdrawAll = false;
        } catch {
            revertedWithdrawAll = true;
        }

        uint256 afterC_final = address(c).balance;
        uint256 afterThis_final = address(this).balance;

        // General rule asserted:
        // 1) If sendMoney reverted, c.balance must be unchanged after that call.
        // 2) If sendMoney succeeded, c.balance must have decreased by exactly 'amount' (or to zero if amount > beforeC),
        //    and the decrease equals min(amount, beforeC).
        // 3) withdrawAll when called by the owner transfers all remaining contract balance to this contract (so c.balance==0)
        //    and this contract's balance increases by exactly the amount withdrawn.

        uint256 expectedDecreaseSend = beforeC >= amount ? amount : beforeC;
        uint256 actualDecreaseSend = beforeC - afterC_send;
        uint256 withdrawAllDecrease = afterC_send - afterC_final;
        uint256 gainedByThisFromWithdraw = afterThis_final - afterThis_send;

        assert(
            // rule part 1 and 2
            (revertedSend && afterC_send == beforeC) || (!revertedSend && actualDecreaseSend == expectedDecreaseSend)
            // rule part 3: withdrawAll must not revert when called by owner and must drain remaining balance
            && revertedWithdrawAll == false
            && afterC_final == 0
            && withdrawAllDecrease == gainedByThisFromWithdraw
            // and the amount withdrawn equals the remaining balance before withdrawAll
            && withdrawAllDecrease == afterC_send
        );
    }

    // receive to accept Ether when withdraw/send happen
    receive() external payable {}
}

